"Play":"Gioca",
"done in {d} days":"fatto in {d} giorni",
"<b>Goal:</b> {goal} · <b>Time:</b> {d} days · start in {city}":"<b>Obiettivo:</b> {goal} · <b>Tempo:</b> {d} giorni · si parte da {city}",
